  const rdA = (width, count) => { const out = []; for (let i = 0; i < count; i++) { const a = p + i * width; let e = a; const cap = a + width; while (e < cap && u8[e] !== 0) e++; out.push(dec.decode(u8.subarray(a, e))); } p += width * count; return out; };
  const names = rdA(33, K);
  p += 2 * (K + 1);
  p += (ver <= 113 ? 12 : 49) * K;
