    autoCodes, autoCodeN: Math.round(autoCodeN * scale),
    distinct, valid: Math.round(nonblank * scale), miss: Math.round((seenN - nonblank) * scale),
    approx: step > 1, mean: numc > 1 ? s / numc : NaN,
