  if(catX){if(xx==null||xx===''){if(o.missing&&onlyX)xx='(Missing)';else continue;}xx=String(xx);}else if(!num(xx))continue;
  if(!onlyX&&!['groupbar','stackcount','likert'].includes(kind)&&!num(yy))continue;
