  if(['dumbbell','slope'].includes(kind)&&!num(lo[i]))continue;
  if(o.groupRequired&&(g[i]==null||g[i]===''))continue;if(o.facetRequired&&(facet[i]==null||facet[i]===''))continue;
  rows.push({x:xx,y:yy,w:ww,g:g[i]==null?'All':String(g[i]),f:facet[i]==null?'All':String(facet[i]),lo:lo[i],hi:hi[i],i});
