  okabe: ['#0072B2', '#E69F00', '#009E73', '#D55E00', '#CC79A7', '#56B4E9', '#8C7B00', '#000000'],
  gray: ['#1F1F1F', '#7A7A7A', '#B5B5B5', '#4A4A4A', '#9A9A9A', '#D0D0D0'],
