// Scripts reproduce the prepared analysis, leaving the original dataset intact.
export function tsScripts(c, prep, res) {
  const { setup, state: S } = c, q = v => JSON.stringify(String(v)), freq = prep.frequency;
  const sq = v => {
    const s = String(v), pieces = s.split(/(["`$\r\n\t\\])/).filter(Boolean).map(x => /^["`$\r\n\t\\]$/.test(x) ? 'char(' + x.charCodeAt(0) + ')' : '"' + x + '"');
    return pieces.length > 1 ? '(' + pieces.join(' + ') + ')' : pieces[0] || '""';
  };
  let p = 'gmts_'; while (c.names.some(n => n.startsWith(p))) p += 'x';
  const t = p + 'time', y = p + 'outcome', u = p + 'unit', trend = p + 'trend', ev = p + 'event', post = p + 'post', since = p + 'since', pulse = p + 'pulse', lag = p + 'lag', nn = p + 'n', valid = p + 'valid', pop = p + 'population';
  const numeric = n => c.numeric.includes(n), literal = (n,v,r=false) => {
    if (!numeric(n)) return r ? q(v) : sq(v);
    const label = (c.valueLabels?.[n] || []).find(x => String(x[1]) === String(v));
    const code = Number.isFinite(Number(v)) ? Number(v) : label ? Number(label[0]) : NaN;
    if (!Number.isFinite(code)) throw new Error('Cannot resolve the stored numeric code for ' + n + ': ' + v);
    return String(code);
  };
  const condition = (x, r) => {
    const v = r ? '`' + x.v + '`' : x.v, val = z => numeric(x.v) && z === '.' ? (r ? 'NA' : '.') : literal(x.v,z,r);
    if (x.t === 'in') return r ? v + ' %in% c(' + x.vals.map(val).join(',') + ')' : '(' + x.vals.map(z => v + ' == ' + val(z)).join(' | ') + ')';
    if (x.t === 'rng') return [x.lo !== '' ? v + ' >= ' + x.lo : '', x.hi !== '' ? v + ' <= ' + x.hi : ''].filter(Boolean).join(' & ');
    if (x.val === '.') return (x.op === '!=' ? '!' : '') + (r ? 'is.na(' : 'missing(') + v + ')';
    return v + ' ' + x.op + ' ' + val(x.val);
  };
  const name = (v,r) => r ? '`' + v + '`' : v;
  const filters = r => c.conditions.map(x => '(' + condition(x,r) + ')').concat(setup.source ? ['(' + name(setup.source,r) + ' == ' + literal(setup.source,S.tsSourceValue,r) + ')'] : []).concat(setup.uv && !S.tsAll ? ['(' + S.tsSel.map(v => name(setup.uv,r) + ' == ' + literal(setup.uv,v,r)).join(' | ') + ')'] : []).filter(Boolean);
  const st = ['preserve', '* ' + c.summary], rr = ['local({', '# ' + c.summary, 'd <- df'];
  for (const [name,codes] of Object.entries(c.missing || {})) if (codes.length) { st.push('replace ' + name + ' = . if ' + codes.map(v => name + ' == ' + v).join(' | ')); rr.push('d$' + name + '[d$' + name + ' %in% c(' + codes.join(',') + ')] <- NA_real_'); }
  const sf = filters(false).join(' & '), rf = filters(true).join(' & ');
  if (sf) st.push('keep if ' + sf); if (rf) rr.push('d <- subset(d, ' + rf + ')');
  const n = setup.frequency === 'quarterly' ? 4 : 12;
  const ti = setup.mode === 'parts' ? (setup.frequency === 'quarterly' ? 'yq' : 'ym') + '(' + setup.tv + ', ' + setup.part + ')' : setup.tv;
  st.push('gen double ' + t + ' = ' + ti);
  rr.push('d$' + t + ' <- ' + (setup.mode === 'parts' ? '(d$' + setup.tv + ' - 1960) * ' + n + ' + d$' + setup.part + ' - 1' : 'd$' + setup.tv));
  const unit = setup.uv || u;
  if (!setup.uv) { st.push('gen byte ' + u + ' = 1'); rr.push('d$' + u + ' <- 1L'); }
  st.push('assert !missing(' + t + ', ' + unit + ')'); if (!prep.collapse) st.push('isid ' + unit + ' ' + t);
  rr.push(prep.collapse ? 'stopifnot(!anyNA(d[c(' + q(unit) + ',' + q(t) + ')]))' : 'stopifnot(!anyNA(d[c(' + q(unit) + ',' + q(t) + ')]), !anyDuplicated(d[c(' + q(unit) + ',' + q(t) + ')]))');
  const ag = S.tsAggregate || 'none', coarser = freq !== setup.frequency;
  const ysrc = ag === 'rate' ? S.tsCount : setup.yv;
  st.push('gen double ' + y + ' = ' + ysrc); rr.push('d$' + y + ' <- d$' + ysrc);
  if (ag === 'rate') { st.push('gen double ' + pop + ' = ' + S.tsPop, 'assert ' + pop + ' > 0 & !missing(' + pop + ')'); rr.push('d$' + pop + ' <- d$' + S.tsPop, 'stopifnot(all(is.finite(d$' + pop + ') & d$' + pop + ' > 0))'); }
  if (coarser) {
    let stc, rc;
    if (setup.frequency === 'monthly') { stc = freq === 'yearly' ? '1960 + floor(' + t + '/12)' : 'floor(' + t + '/3)'; rc = freq === 'yearly' ? '1960 + floor(d$' + t + '/12)' : 'floor(d$' + t + '/3)'; }
    else if (setup.frequency === 'quarterly') { stc = '1960 + floor(' + t + '/4)'; rc = '1960 + floor(d$' + t + '/4)'; }
    else { stc = (freq === 'yearly' ? 'year(' + t + ')' : freq === 'monthly' ? 'mofd(' + t + ')' : 'qofd(' + t + ')'); rr.push('calendar <- as.Date(d$' + t + ', origin="1960-01-01")'); rc = freq === 'yearly' ? 'as.integer(format(calendar,"%Y"))' : '(as.integer(format(calendar,"%Y"))-1960)*' + (freq === 'monthly' ? '12 + as.integer(format(calendar,"%m"))-1' : '4 + (as.integer(format(calendar,"%m"))-1) %/% 3'); }
    st.push('replace ' + t + ' = ' + stc); rr.push('d$' + t + ' <- ' + rc);
  }
  for (const [k,op] of [['tsT0','>='],['tsT1','<=']]) { const v = tsPeriod(S[k],freq); if (Number.isFinite(v)) { st.push('keep if ' + t + ' ' + op + ' ' + v); rr.push('d <- d[d$' + t + ' ' + op + ' ' + v + ',,drop=FALSE]'); } }
  if (prep.collapse) {
    // records → one value per unit and period, like Stata's collapse (weights for mean, median and sum)
    const stat = prep.collapse, w = S.tsW || '', wt = w && ['mean', 'median', 'sum'].includes(stat), lo = p + 'min';
    st.push('drop if missing(' + y + ')'); if (w) st.push('drop if missing(' + w + ') | ' + w + ' <= 0');
    st.push(stat === 'range' ? 'collapse (max) ' + y + ' (min) ' + lo + '=' + y + ', by(' + unit + ' ' + t + ')' : 'collapse (' + stat + ') ' + y + (wt ? ' [pw=' + w + ']' : '') + ', by(' + unit + ' ' + t + ')');
    if (stat === 'range') st.push('replace ' + y + ' = ' + y + ' - ' + lo);
    rr.push('d <- d[is.finite(d$' + y + ')' + (w ? ' & is.finite(d$' + w + ') & d$' + w + ' > 0' : '') + ',,drop=FALSE]');
    if (stat === 'median' && wt) rr.push('wmedian <- function(x, w) { o <- order(x); x <- x[o]; cw <- cumsum(w[o]); h <- sum(w)/2; j <- which(cw >= h - 1e-12)[1]; if (abs(cw[j] - h) <= 1e-12 && j < length(x)) (x[j] + x[j+1])/2 else x[j] }');
    const gy = 'g$' + y, gw = 'g$' + w;
    const f = { mean: wt ? 'weighted.mean(' + gy + ', ' + gw + ')' : 'mean(' + gy + ')', median: wt ? 'wmedian(' + gy + ', ' + gw + ')' : 'median(' + gy + ')', sum: wt ? 'sum(' + gw + ' * ' + gy + ')' : 'sum(' + gy + ')', min: 'min(' + gy + ')', max: 'max(' + gy + ')', range: 'diff(range(' + gy + '))' }[stat];
    rr.push('d <- do.call(rbind, lapply(split(d, interaction(d$' + unit + ',d$' + t + ',drop=TRUE)), function(g) {', '  b <- g[1,,drop=FALSE]', '  b$' + y + ' <- ' + f, '  b', '}))');
  }
  if (coarser && !prep.collapse) {
    let expectedSt, expectedR;
    if (setup.frequency === 'monthly' || setup.frequency === 'quarterly') expectedSt = expectedR = String(setup.frequency === 'quarterly' ? 4 : freq === 'yearly' ? 12 : 3);
    else { expectedSt = freq === 'yearly' ? 'mdy(1,1,' + t + '+1)-mdy(1,1,' + t + ')' : freq === 'monthly' ? 'dofm(' + t + '+1)-dofm(' + t + ')' : 'dofq(' + t + '+1)-dofq(' + t + ')'; expectedR = freq === 'yearly' ? 'as.numeric(as.Date(paste0(b$' + t + '+1,"-01-01"))-as.Date(paste0(b$' + t + ',"-01-01")))' : 'as.numeric(seq(as.Date("1960-01-01") + 0, length.out=1)[1])'; }
    st.push('gen byte ' + nn + ' = 1', 'gen byte ' + valid + ' = !missing(' + y + ')');
    if (ag === 'rate') st.push('bysort ' + unit + ' ' + t + ': assert ' + pop + ' == ' + pop + '[1]');
    st.push('collapse (sum) ' + y + ' ' + nn + ' ' + valid + (ag === 'rate' ? ' (firstnm) ' + pop : '') + ', by(' + unit + ' ' + t + ')', 'replace ' + y + ' = . if ' + nn + ' != ' + expectedSt + ' | ' + valid + ' != ' + nn);
    if (ag === 'mean') st.push('replace ' + y + ' = ' + y + '/' + nn);
    const expectedDaily = freq === 'yearly' ? expectedR : 'as.numeric(as.Date(sprintf("%04d-%02d-01",1960+(b$' + t + ' %/% ' + (freq === 'monthly' ? 12 : 4) + '), (b$' + t + ' %% ' + (freq === 'monthly' ? 12 : 4) + ')*' + (freq === 'monthly' ? 1 : 3) + '+1)) + 0)';
    rr.push('d <- do.call(rbind, lapply(split(d, interaction(d$' + unit + ',d$' + t + ',drop=TRUE)), function(g) {', '  b <- g[1,,drop=FALSE]');
    if (setup.frequency === 'daily' && freq !== 'yearly') rr.push('  begin <- as.Date(sprintf("%04d-%02d-01",1960+b$' + t + ' %/% ' + (freq === 'monthly' ? 12 : 4) + ', (b$' + t + ' %% ' + (freq === 'monthly' ? 12 : 4) + ')*' + (freq === 'monthly' ? 1 : 3) + '+1))', '  expected <- as.numeric(seq(begin,by="' + (freq === 'monthly' ? 'month' : '3 months') + '",length.out=2)[2]-begin)');
    else rr.push('  expected <- ' + expectedDaily);
    if (ag === 'rate') rr.push('  stopifnot(length(unique(g$' + pop + ')) == 1L)');
    rr.push('  b$' + y + ' <- if(nrow(g)!=expected || anyNA(g$' + y + ')) NA_real_ else ' + (ag === 'mean' ? 'mean' : 'sum') + '(g$' + y + ')', '  b', '}))');
  }
  if (ag === 'rate') { const scale = Number(S.tsScale || 100000); st.push('replace ' + y + ' = ' + y + '/' + pop + '*' + scale); rr.push('d$' + y + ' <- d$' + y + '/d$' + pop + '*' + scale); }
  // Values typed in the app for missing periods are written into the scripts, so they reproduce the same series.
  const fills = (prep.missing || []).filter(m => m.fill !== null);
  if (fills.length) {
    st.push('* ' + fills.length + ' missing period(s) filled with values entered in the app (assumptions, not observed data)'); rr.push('# ' + fills.length + ' missing period(s) filled with values entered in the app (assumptions, not observed data)');
    for (const m of fills) {
      const us = setup.uv ? name(setup.uv,false) + ' == ' + literal(setup.uv,m.u) : u + ' == 1', ur = setup.uv ? 'd$' + setup.uv + ' == ' + literal(setup.uv,m.u,true) : 'd$' + u + ' == 1L';
      st.push('drop if ' + us + ' & ' + t + ' == ' + m.t, 'set obs `=_N+1\'', 'replace ' + (setup.uv ? name(setup.uv,false) + ' = ' + literal(setup.uv,m.u) : u + ' = 1') + ' in l', 'replace ' + t + ' = ' + m.t + ' in l', 'replace ' + y + ' = ' + m.fill + ' in l');
      rr.push('d <- d[!(' + ur + ' & d$' + t + ' == ' + m.t + '),,drop=FALSE]', 'd[nrow(d)+1, c(' + q(setup.uv || u) + ',' + q(t) + ',' + q(y) + ')] <- list(' + (setup.uv ? literal(setup.uv,m.u,true) : '1L') + ', ' + m.t + ', ' + m.fill + ')');
    }
  }
  if (S.tsAvg && prep.nUnits > 1) { st.push('collapse (mean) ' + y + ', by(' + t + ')', 'gen byte ' + u + ' = 1'); rr.push('d <- aggregate(d[' + q(y) + '], list(' + t + '=d$' + t + '), mean)', 'd$' + u + ' <- 1L'); }
  else if (setup.uv) { st.push('egen long ' + u + ' = group(' + setup.uv + ')'); rr.push('d$' + u + ' <- as.integer(factor(d$' + setup.uv + '))'); }
  const formats = {monthly:'tm',quarterly:'tq',daily:'td',weekly:'tw'};
  if (formats[freq]) st.push('format ' + t + ' %' + formats[freq]);
  st.push('drop if missing(' + y + ')', (res.pooled ? 'xtset ' + u + ' ' : 'tsset ') + t + (prep.step > 1 ? ', delta(' + prep.step + ')' : ''));
  rr.push('d <- d[is.finite(d$' + y + '),,drop=FALSE]', 'd <- d[order(d$' + u + ',d$' + t + '),,drop=FALSE]');
  const tr = S.tsTr || 'level', orig = p + 'original';
  if (tr !== 'level') { st.push('gen double ' + orig + ' = ' + y, 'replace ' + y + ' = ' + (tr === 'diff' ? orig + '-L.' + orig : '100*(' + orig + '/L.' + orig + '-1)') + (tr === 'pct' ? ' if L.' + orig + ' != 0' : ''), ...(tr === 'pct' ? ['replace ' + y + ' = . if L.' + orig + ' == 0'] : [])); rr.push('d$' + y + ' <- ave(d$' + y + ', d$' + u + ', FUN=function(x) c(NA_real_, ' + (tr === 'diff' ? 'diff(x)' : 'ifelse(head(x,-1)==0,NA_real_,100*(tail(x,-1)/head(x,-1)-1))') + '))'); }
  st.push('gen double ' + trend + ' = ' + t + ' - ' + res.tmin); rr.push('d$' + trend + ' <- d$' + t + ' - ' + res.tmin);
  const terms = [trend];
  if (res.hasEv) {
    const e0 = Number.isFinite(c.common) ? c.common : null; st.push('gen double ' + ev + ' = ' + (e0 ?? '.')); rr.push('d$' + ev + ' <- ' + (e0 ?? 'NA_real_'));
    for (const [raw,value] of Object.entries(c.events)) { st.push('replace ' + ev + ' = ' + value + ' if ' + setup.uv + ' == ' + literal(setup.uv,raw)); rr.push('d$' + ev + '[d$' + setup.uv + ' == ' + literal(setup.uv,raw,true) + '] <- ' + value); }
    st.push('gen byte ' + post + ' = ' + t + ' >= ' + ev + ' if !missing(' + ev + ')', 'gen double ' + since + ' = max(0,' + t + '-' + ev + ') if !missing(' + ev + ')', 'gen byte ' + pulse + ' = ' + t + ' == ' + ev + ' if !missing(' + ev + ')');
    rr.push('d$' + post + ' <- as.numeric(d$' + t + ' >= d$' + ev + ')', 'd$' + since + ' <- pmax(0,d$' + t + '-d$' + ev + ')', 'd$' + pulse + ' <- as.numeric(d$' + t + ' == d$' + ev + ')');
    if (['step','both'].includes(S.tsType || 'both')) terms.push(post); if (['trend','both'].includes(S.tsType || 'both')) terms.push(since); if (S.tsType === 'pulse') terms.push(pulse);
  }
  if (S.tsAr1) { st.push('gen double ' + lag + ' = L.' + y); rr.push('d$' + lag + ' <- ave(d$' + y + ',d$' + u + ',FUN=function(x)c(NA_real_,head(x,-1)))'); terms.push(lag); }
  const L = Number((res.seType.match(/lag (\d+)/) || [0,1])[1]);
  st.push((res.pooled ? 'regress ' : 'newey ') + y + ' ' + terms.map(x => 'c.' + x).join(' ') + (res.pooled ? ' i.' + u + ', vce(cluster ' + u + ')' : ', lag(' + L + ')'), 'restore');
  rr.push('library(sandwich); library(lmtest)', 'm <- lm(' + y + ' ~ ' + terms.join(' + ') + (res.pooled ? ' + factor(' + u + ')' : '') + ',data=d,na.action=na.omit)', 'coeftest(m, vcov. = ' + (res.pooled ? 'vcovCL(m,cluster=~' + u + ',type="HC1",cadjust=TRUE), df=' + (res.nUnits-1) : 'NeweyWest(m,lag=' + L + ',prewhite=FALSE,adjust=TRUE)') + ')', '})');
  const rx = x => x.replace(/\b([dgb])\$([A-Za-z_][A-Za-z0-9_]*)/g,(_,obj,key)=>obj+'[['+q(key)+']]');
  // The console shows the key lines only; the full script goes to the .do / .R download and "Stata / R script".
  const about = 'trend / interrupted time series of ' + setup.yv + ' over ' + setup.tv + (setup.uv ? ', units ' + setup.uv : '') + (prep.collapse ? ', records collapsed (' + prep.collapse + ')' : '') + ' — full script under "Stata / R script"';
  const short = { stata: ['* ' + about, ...st.filter(x => /^(collapse|xtset|tsset|regress|newey) /.test(x))].join('\n'), r: rx(['# ' + about, ...rr.filter(x => /^(m <- lm\(|coeftest\()/.test(x))].join('\n')) };
  return { stata: st.join('\n'), r: rx(rr.join('\n')), short };
}

// Summary of a unit-period's records (Stata collapse): mean, median, sum, min, max or range; weights apply to
// mean (weighted mean), median (weighted median) and sum (weighted total).
export function tsCollapseValue(v, w, stat) {
  const n = v.length; if (!n) return NaN;
  if (stat === 'min' || stat === 'max' || stat === 'range') { let lo = Infinity, hi = -Infinity; for (const x of v) { if (x < lo) lo = x; if (x > hi) hi = x; } return stat === 'min' ? lo : stat === 'max' ? hi : hi - lo; }
  if (stat === 'sum') { let s = 0; for (let i = 0; i < n; i++) s += v[i] * w[i]; return s; }
  if (stat === 'median') {
    const ix = Array.from({ length: n }, (_, i) => i).sort((a, b) => v[a] - v[b]); let tot = 0; for (const x of w) tot += x;
    let c = 0; for (let k = 0; k < n; k++) { c += w[ix[k]]; if (c > tot / 2 + 1e-12) return v[ix[k]]; if (Math.abs(c - tot / 2) <= 1e-12) return (v[ix[k]] + v[ix[k + 1]]) / 2; }
    return v[ix[n - 1]];
  }
  let s = 0, sw = 0; for (let i = 0; i < n; i++) { s += v[i] * w[i]; sw += w[i]; } return s / sw;
}

// GM26 time-series module end

// GM26 time-series dates begin
// Reading time variables for GM26.1 (Stata tsset-style). Bundled into the engine; no network dependencies.
// Period codes follow the calculator's existing calendar: annual = year, quarterly = quarters since 1960q1,
// monthly = months since 1960m1, daily = days since 1960-01-01. Text dates are converted, never guessed
// silently: ambiguous day/month order is reported and can be set explicitly.

const MONTHS = { jan: 1, ene: 1, january: 1, enero: 1, feb: 2, february: 2, febrero: 2, mar: 3, march: 3, marzo: 3,
  apr: 4, abr: 4, april: 4, abril: 4, may: 5, mayo: 5, jun: 6, june: 6, junio: 6, jul: 7, july: 7, julio: 7,
  aug: 8, ago: 8, august: 8, agosto: 8, sep: 9, sept: 9, set: 9, september: 9, septiembre: 9, setiembre: 9,
  oct: 10, october: 10, octubre: 10, nov: 11, november: 11, noviembre: 11, dec: 12, dic: 12, december: 12, diciembre: 12 };
const DAY0 = Date.UTC(1960, 0, 1);

export const TSD_FREQ = {
  yearly: { label: 'Annual', unit: 'year', units: 'years', cycle: 1 },
  quarterly: { label: 'Quarterly', unit: 'quarter', units: 'quarters', cycle: 4 },
  monthly: { label: 'Monthly', unit: 'month', units: 'months', cycle: 12 },
  weekly: { label: 'Weekly', unit: 'week', units: 'weeks', cycle: 52 },
  daily: { label: 'Daily', unit: 'day', units: 'days', cycle: 7 },
  trading: { label: 'Trading days', unit: 'trading day', units: 'trading days', cycle: 5 },
  generic: { label: 'Integer periods', unit: 'period', units: 'periods', cycle: 1 },
};

function dayCode(y, m, d) {
  if (!(y >= 1000 && y <= 2999 && m >= 1 && m <= 12 && d >= 1 && d <= 31)) return NaN;
  const t = Date.UTC(y, m - 1, d), x = new Date(t);
  return x.getUTCFullYear() === y && x.getUTCMonth() === m - 1 && x.getUTCDate() === d ? Math.round((t - DAY0) / 86400000) : NaN;
}
const monthCode = (y, m) => (y >= 1000 && y <= 2999 && m >= 1 && m <= 12 ? (y - 1960) * 12 + m - 1 : NaN);
const quarterCode = (y, q) => (y >= 1000 && y <= 2999 && q >= 1 && q <= 4 ? (y - 1960) * 4 + q - 1 : NaN);
const monthName = s => MONTHS[String(s).toLowerCase().replace(/\.$/, '')] || 0;

// One text value → [frequency, code, slash-order info]; slash dates return both readings.
function readOne(raw) {
  const s = String(raw).trim().replace(/\s+/g, ' ');
  if (!s) return null;
  let m;
  if ((m = s.match(/^(\d{4})[-/.](\d{1,2})[-/.](\d{1,2})(?:[ T].*)?$/))) return ['daily', dayCode(+m[1], +m[2], +m[3])];
  if ((m = s.match(/^(\d{4})[-/.](\d{1,2})$/))) return ['monthly', monthCode(+m[1], +m[2])];
  if ((m = s.match(/^(\d{4}) ?[mM](\d{1,2})$/))) return ['monthly', monthCode(+m[1], +m[2])];
  if ((m = s.match(/^(\d{4}) ?[-/ ]? ?[qQ]([1-4])$/))) return ['quarterly', quarterCode(+m[1], +m[2])];
  if ((m = s.match(/^[qQ]([1-4]) ?[-/ ]? ?(\d{4})$/))) return ['quarterly', quarterCode(+m[2], +m[1])];
  if ((m = s.match(/^(\d{4})$/))) return ['yearly', +m[1]];
  if ((m = s.match(/^([A-Za-zÀ-ÿ]{3,10})\.? (\d{1,2}),? (\d{4})$/)) && monthName(m[1])) return ['daily', dayCode(+m[3], monthName(m[1]), +m[2])];
  if ((m = s.match(/^(\d{1,2})[ -]?(?:de )?([A-Za-zÀ-ÿ]{3,10})\.?,?[ -]?(?:de )?(\d{4})$/)) && monthName(m[2])) return ['daily', dayCode(+m[3], monthName(m[2]), +m[1])];
  if ((m = s.match(/^([A-Za-zÀ-ÿ]{3,10})\.?[ -](?:de )?(\d{4})$/)) && monthName(m[1])) return ['monthly', monthCode(+m[2], monthName(m[1]))];
  if ((m = s.match(/^(\d{4})[ -]([A-Za-zÀ-ÿ]{3,10})$/)) && monthName(m[2])) return ['monthly', monthCode(+m[1], monthName(m[2]))];
  if ((m = s.match(/^(\d{1,2})[/.-](\d{1,2})[/.-](\d{4})$/))) return ['slash', null, +m[1], +m[2], +m[3]];
  return ['bad', NaN];
}

// Reads a text column. order: 'auto' | 'mdy' | 'dmy' (only used for 11/01/2011-style dates).
export function tsdReadText(values, order = 'auto') {
  const kinds = new Map(), parsed = new Array(values.length);
  let firstBig = 0, secondBig = 0, slashN = 0;
  for (let i = 0; i < values.length; i++) {
    const v = values[i];
    if (v == null || String(v).trim() === '') { parsed[i] = null; continue; }
    const r = readOne(v); parsed[i] = r;
    if (r[0] === 'slash') { slashN++; if (r[2] > 12) firstBig++; if (r[3] > 12) secondBig++; }
    kinds.set(r[0], (kinds.get(r[0]) || 0) + 1);
  }
  let resolved = order;
  if (slashN && order === 'auto') resolved = firstBig && !secondBig ? 'dmy' : secondBig && !firstBig ? 'mdy' : firstBig && secondBig ? 'mixed' : 'ambiguous';
  const good = [...kinds].filter(([k]) => k !== 'bad').sort((a, b) => b[1] - a[1]);
  let freq = good.length ? good[0][0] : '';
  if (freq === 'slash') freq = 'daily';
  const codes = new Float64Array(values.length).fill(NaN), bad = [];
  let invalid = 0, blank = 0;
  for (let i = 0; i < values.length; i++) {
    const r = parsed[i];
    if (!r) { blank++; continue; }
    let f = r[0], c = r[1];
    if (f === 'slash') { f = 'daily'; const o = resolved === 'dmy' ? 'dmy' : 'mdy'; c = o === 'dmy' ? dayCode(r[4], r[3], r[2]) : dayCode(r[4], r[2], r[3]); }
    if (f !== freq || !Number.isFinite(c)) { invalid++; if (bad.length < 3) bad.push(String(values[i])); continue; }
    codes[i] = c;
  }
  return { freq, codes, invalid, blank, bad, slash: slashN > 0, order: resolved, ambiguous: slashN > 0 && (resolved === 'ambiguous' || resolved === 'mixed') && order === 'auto' };
}

// A numeric column: years (1000–2999 integers) or integer periods unless told otherwise.
export function tsdReadNumber(values, as = 'auto') {
  const codes = new Float64Array(values.length).fill(NaN); let invalid = 0, blank = 0, years = true, ints = true, any = false;
  for (let i = 0; i < values.length; i++) {
    const v = values[i];
    if (v == null || !Number.isFinite(v)) { blank++; continue; }
    any = true; if (!Number.isInteger(v)) ints = false; if (!(Number.isInteger(v) && v >= 1000 && v <= 2999)) years = false;
  }
  let freq = as;
  if (as === 'auto') freq = !any ? '' : years ? 'yearly' : ints ? 'generic' : '';
  for (let i = 0; i < values.length; i++) {
    const v = values[i];
    if (v == null || !Number.isFinite(v)) continue;
    if (!Number.isInteger(v)) { invalid++; continue; }
    codes[i] = v;
  }
  return { freq, codes, invalid, blank, bad: [], numeric: true, nonInteger: any && !ints };
}

export function tsdLabel(code, freq) {
  if (!Number.isFinite(code)) return '—';
  const t = Math.round(code);
  if (freq === 'monthly') return (1960 + Math.floor(t / 12)) + 'm' + ((((t % 12) + 12) % 12) + 1);
  if (freq === 'quarterly') return (1960 + Math.floor(t / 4)) + 'q' + ((((t % 4) + 4) % 4) + 1);
  if (freq === 'daily' || freq === 'trading') { const d = new Date(DAY0 + t * 86400000); return d.getUTCDate() + ' ' + ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'][d.getUTCMonth()] + ' ' + d.getUTCFullYear(); }
  return String(t);
}

// The value R receives as its time index: decimal years for months/quarters (so R plots read as years),
// the year for annual data, and the position 1..T otherwise.
export function tsdIndex(code, freq, pos) {
  if (freq === 'monthly') return 1960 + code / 12;
  if (freq === 'quarterly') return 1960 + code / 4;
  if (freq === 'yearly' || freq === 'generic') return code;
  return pos + 1;
}

// tsset + series preparation. o: { time: codes, freq, unit (values|null), unitPick (label|'' ), combine ('' | 'mean' | 'sum'),
//   repeats ('' | 'mean' | 'sum'), vars: { name: Float64Array }, mask, unitLabel(v) }.
