// ---- recipe → features
// recipe: { url:'remove', num:'remove', emoji:'remove', tag:'keep'|'word'|'remove', mention:'keep'|'remove',
//           hyphen:'keep'|'split', fold:bool, langs:[], stopSource:'snowball'|'iso', extra:[], minLen:2,
