  for (const r of grid) if (r) for (let c = 0; c < r.length; c++) { const v = r[c]; if (v && typeof v === 'object' && (v.k === 'datetime' || (v.k === 'date' && Math.abs(v.d - Math.floor(v.d)) > 1e-7))) hasTime[c] = true; }
